package org.telegram.messenger.tetogram;
import org.junit.Test;
import org.junit.Rule;
import org.junit.rules.TemporaryFolder;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.*;
import java.util.zip.*;
import static org.junit.Assert.*;
public class AppearanceArchiveTest {
    @Rule public TemporaryFolder temp=new TemporaryFolder();
    private AppearanceConfig.Preset preset(){AppearanceConfig.Preset p=new AppearanceConfig.Preset();p.name="Тема 🌈";p.style.color(false,"chat_outBubble",0xffabcdef);return p;}
    private byte[] zip(String manifest,String entry,byte[] content)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(b)){z.putNextEntry(new ZipEntry("appearance.properties"));z.write(manifest.getBytes(StandardCharsets.UTF_8));z.closeEntry();if(entry!=null){z.putNextEntry(new ZipEntry(entry));z.write(content);z.closeEntry();}}return b.toByteArray();}
    private void rejected(byte[] zip)throws Exception{File stage=temp.newFolder();try{AppearanceArchive.read(new ByteArrayInputStream(zip),stage);fail("Accepted unsafe archive");}catch(IOException expected){assertEquals(0,Objects.requireNonNull(stage.list()).length);}}
    @Test public void paletteRoundTripHasFreshIdAndNoScopes()throws Exception{AppearanceConfig.Preset p=preset();ByteArrayOutputStream out=new ByteArrayOutputStream();AppearanceArchive.write(out,p,n->null,false,false);AppearanceArchive.Imported read=AppearanceArchive.read(new ByteArrayInputStream(out.toByteArray()),temp.newFolder());assertEquals(p.name,read.preset.name);assertNotEquals(p.id,read.preset.id);assertEquals(p.style.values,read.preset.style.values);assertTrue(read.files.isEmpty());}
    @Test public void imagesAreOptInAndRenamedWithStableSharedReferences()throws Exception{String name=UUID.randomUUID()+".jpg";File original=temp.newFile(name);Files.write(original.toPath(),new byte[]{1,2,3,4});AppearanceConfig.Preset p=preset();p.style.set("wallpaper.file",name);p.style.set("list.wallpaper.file",name);p.style.set("wallpaper.source.file",UUID.randomUUID()+".mp4");ByteArrayOutputStream out=new ByteArrayOutputStream();AppearanceArchive.write(out,p,n->original,true,false);AppearanceArchive.Imported read=AppearanceArchive.read(new ByteArrayInputStream(out.toByteArray()),temp.newFolder());assertEquals(1,read.files.size());String renamed=read.preset.style.values.get("wallpaper.file");assertNotEquals(name,renamed);assertEquals(renamed,read.preset.style.values.get("list.wallpaper.file"));assertNull(read.preset.style.values.get("wallpaper.source.file"));assertArrayEquals(new byte[]{1,2,3,4},Files.readAllBytes(read.files.get(0).toPath()));out.reset();AppearanceArchive.write(out,p,n->original,false,false);assertNull(AppearanceArchive.read(new ByteArrayInputStream(out.toByteArray()),temp.newFolder()).preset.style.values.get("wallpaper.file"));}
    @Test public void refusingVideoCanExportOnlyItsCover()throws Exception{String cover=UUID.randomUUID()+".jpg",video=UUID.randomUUID()+".mp4";File f=temp.newFile();Files.write(f.toPath(),new byte[]{1});AppearanceConfig.Preset p=preset();p.style.set("wallpaper.type","video");p.style.set("wallpaper.file",video);p.style.set("wallpaper.cover.file",cover);ByteArrayOutputStream out=new ByteArrayOutputStream();AppearanceArchive.write(out,p,n->{assertEquals(cover,n);return f;},true,false);AppearanceArchive.Imported r=AppearanceArchive.read(new ByteArrayInputStream(out.toByteArray()),temp.newFolder());assertEquals("image",r.preset.style.values.get("wallpaper.type"));assertEquals(r.preset.style.values.get("wallpaper.file"),r.preset.style.values.get("wallpaper.cover.file"));}
    @Test public void rejectsUnsafePathsUnknownMetadataAndFutureSchema()throws Exception{String base="format=TetogramAppearance\nschema=1\n";for(String path:new String[]{"../outside","media/../../outside","/absolute","media/"+UUID.randomUUID()+".jpg"})rejected(zip(base,path,new byte[]{1}));rejected(zip(base+"accountId=123\n",null,null));rejected(zip("format=TetogramAppearance\nschema=2\n",null,null));rejected(zip(base+"style.wallpaper.file=../bad\n",null,null));rejected(zip(base+"style.wallpaper.source.file="+UUID.randomUUID()+".jpg\n",null,null));}
    @Test public void rejectsChecksumMismatchAndMissingAssetsAndCleansStaging()throws Exception{String name=UUID.randomUUID()+".jpg",manifest="format=TetogramAppearance\nschema=1\nstyle.wallpaper.file="+name+"\nsha256."+name+"="+String.join("",Collections.nCopies(64,"0"))+"\n";rejected(zip(manifest,"media/"+name,new byte[]{1}));rejected(zip(manifest,null,null));}
    @Test public void manifestIsBounded()throws Exception{rejected(zip("format=TetogramAppearance\nschema=1\n#"+String.join("",Collections.nCopies(600000,"x")),null,null));}
}
